static void low_power_timer_event_cb(struct _lv_timer_t *timer)
{
    lv_obj_t *      ui_Screen;
    ui_screen_remind_news_obj_t * p_screen_param;

    ui_Screen           = timer->user_data;
    p_screen_param      = (ui_screen_remind_news_obj_t *) lv_obj_get_user_data(ui_Screen);

    if (p_screen_param->handle_timer) {
        lv_timer_pause(p_screen_param->handle_timer);

        if (p_screen_param->low_power_type) {
            remind_fp_win_exit_current_ui();
            }
        else {
            lv_obj_t *      frist_win;
            lv_obj_t *      app;

            app                 = get_app_by_name("idle_fp");
            frist_win           = get_win_by_name(app,"power_off");
            alv_am_app_set_first_win(app,frist_win);
            alv_am_app_enter_action(NULL,"idle_fp",NULL);

            }
        }
}


